$('#logActor').addEventListener('change',e=>{logActor=e.target.value;renderEvents()});
$('#logKind').addEventListener('change',e=>{logKind=e.target.value;renderEvents()});
$('#logDate').addEventListener('change',e=>{logDate=e.target.value;renderEvents()});
$('#clearLogFilters').addEventListener('click',()=>{logQuery='';logActor='ALL';logKind='ALL';logDate='';$('#logSearch').value='';$('#logDate').value='';renderEvents()});
$('#previewMission').addEventListener('change',e=>{previewPinned=true;previewMissionId=e.target.value;previewTaskId='';renderPreview()});
