new ResizeObserver(()=>fitPreview()).observe($('#previewMonitor'));
$('#routes').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),d=Object.fromEntries(f);d.enabled=f.has('enabled');try{await api(`/api/routes/${e.target.dataset.member}`,{method:'POST',body:JSON.stringify(d)});toast('Route saved.');await load()}catch(x){toast(x.message)}});
$('#projectForm').addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await api('/api/projects',{method:'POST',body:JSON.stringify(d)});$('#project').value=d.name;toast('Project registered. The studio knows its boundaries.');await load()}catch(x){toast(x.message)}});
$('#missionText').addEventListener('input',e=>$('#missionCount').textContent=e.target.value.length);
function applyTheme(name){const colors=THEMES[name]||THEMES.gold;document.documentElement.style.setProperty('--gold',colors[0]);document.documentElement.style.setProperty('--gold2',colors[1]);localStorage.setItem('lcn-theme',name);document.querySelectorAll('[data-theme]').forEach(b=>b.classList.toggle('on',b.dataset.theme===name))}
let customHue=42,customSat=.62,customBrightness=1;
function clamp(v,min,max){return Math.max(min,Math.min(max,v))}
function hsvToRgb(h,s,v){const i=Math.floor(h*6),f=h*6-i,p=v*(1-s),q=v*(1-f*s),t=v*(1-(1-f)*s),sets=[[v,t,p],[q,v,p],[p,v,t],[p,q,v],[t,p,v],[v,p,q]],rgb=sets[i%6];return rgb.map(n=>Math.round(n*255))}
function rgbToHsv(r,g,b){r/=255;g/=255;b/=255;const max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0;if(d){if(max===r)h=((g-b)/d)%6;else if(max===g)h=(b-r)/d+2;else h=(r-g)/d+4;h/=6;if(h<0)h+=1}return[h,max?d/max:0,max]}
function rgbHex(r,g,b){return'#'+[r,g,b].map(n=>clamp(Math.round(n),0,255).toString(16).padStart(2,'0')).join('')}
function hexRgb(hex){const m=/^#?([0-9a-f]{6})$/i.exec(hex.trim());return m?[parseInt(m[1].slice(0,2),16),parseInt(m[1].slice(2,4),16),parseInt(m[1].slice(4,6),16)]:null}
function drawColorWheel(){const canvas=$('#colorWheel'),ctx=canvas.getContext('2d'),w=canvas.width,c=w/2,r=c,img=ctx.createImageData(w,w);for(let y=0;y<w;y++)for(let x=0;x<w;x++){const dx=x-c,dy=y-c,d=Math.sqrt(dx*dx+dy*dy),o=(y*w+x)*4;if(d<=r){const h=(Math.atan2(dy,dx)/(Math.PI*2)+1)%1,s=d/r,[rr,gg,bb]=hsvToRgb(h,s,1);img.data[o]=rr;img.data[o+1]=gg;img.data[o+2]=bb;img.data[o+3]=255}}ctx.putImageData(img,0,0)}
function drawBrightness(rgb){const canvas=$('#brightnessBar'),ctx=canvas.getContext('2d'),g=ctx.createLinearGradient(0,0,canvas.width,0);g.addColorStop(0,'#000');g.addColorStop(1,rgbHex(...rgb));ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle=g;ctx.fillRect(0,0,canvas.width,canvas.height)}
function setCustomColor(rgb,{persist=false,moveCursor=true}={}){const [r,g,b]=rgb.map(n=>clamp(Number(n)||0,0,255)),[h,s,v]=rgbToHsv(r,g,b);customHue=h;customSat=s;customBrightness=v;const base=hsvToRgb(h,s,1),actual=hsvToRgb(h,s,customBrightness),highlight=actual.map(n=>Math.round(n+(255-n)*.38)),hex=rgbHex(...actual);document.documentElement.style.setProperty('--gold',hex);document.documentElement.style.setProperty('--gold2',rgbHex(...highlight));document.documentElement.style.setProperty('--custom-color',hex);$('#colorR').value=actual[0];$('#colorG').value=actual[1];$('#colorB').value=actual[2];$('#colorHex').value=hex;$('#colorBrightness').value=Math.round(customBrightness*100);if(moveCursor){const rad=customHue*Math.PI*2,dist=customSat*110;$('#colorCursor').style.left=`${110+Math.cos(rad)*dist}px`;$('#colorCursor').style.top=`${110+Math.sin(rad)*dist}px`}drawBrightness(base);document.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('on',b.dataset.color.toLowerCase()===hex));if(persist)localStorage.setItem('lcn-custom-color',hex)}
function selectWheel(e){const canvas=$('#colorWheel'),box=canvas.getBoundingClientRect(),x=(e.clientX-box.left)/box.width*canvas.width,y=(e.clientY-box.top)/box.height*canvas.height,c=canvas.width/2,dx=x-c,dy=y-c,d=Math.min(c,Math.sqrt(dx*dx+dy*dy));customHue=(Math.atan2(dy,dx)/(Math.PI*2)+1)%1;customSat=d/c;setCustomColor(hsvToRgb(customHue,customSat,customBrightness))}
function setClockMode(mode){clockMode=mode==='digital'?'digital':'analog';document.querySelector('.now').dataset.clockMode=clockMode;$('#analogClock').hidden=clockMode!=='analog';document.querySelectorAll('[data-clock]').forEach(b=>b.classList.toggle('on',b.dataset.clock===clockMode));localStorage.setItem('lcn-clock-v2',clockMode);tick()}
function drawAnalog(now){const canvas=$('#analogClock'),ctx=canvas.getContext('2d'),size=240,c=120,styles=getComputedStyle(document.documentElement),accent=styles.getPropertyValue('--gold2').trim()||'#f0d48a',authority=styles.getPropertyValue('--gold').trim()||'#d4ae55';ctx.clearRect(0,0,size,size);ctx.save();ctx.translate(.5,.5);const ring=(r,w,color)=>{ctx.beginPath();ctx.arc(c,c,r,0,Math.PI*2);ctx.lineWidth=w;ctx.strokeStyle=color;ctx.stroke()};ring(116,2,'rgba(240,235,225,.1)');ring(110,1,authority);ring(103,1,'rgba(240,235,225,.22)');ring(83,1,'rgba(240,235,225,.08)');for(let i=0;i<60;i++){const a=i*Math.PI/30-Math.PI/2,major=i%5===0,quarter=i%15===0,outer=99,inner=quarter?84:major?89:94;ctx.beginPath();ctx.moveTo(c+Math.cos(a)*inner,c+Math.sin(a)*inner);ctx.lineTo(c+Math.cos(a)*outer,c+Math.sin(a)*outer);ctx.lineWidth=quarter?3:major?2:1;ctx.strokeStyle=quarter?accent:major?'rgba(238,233,223,.78)':'rgba(238,233,223,.28)';ctx.stroke()}ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#eee9df';ctx.font='600 20px "Arial Narrow", "Segoe UI", sans-serif';[['12',0,-68],['3',69,0],['6',0,69],['9',-69,0]].forEach(([n,x,y])=>ctx.fillText(n,c+x,c+y));ctx.fillStyle=authority;ctx.font='800 8px "Arial Narrow", "Segoe UI", sans-serif';ctx.fillText('R U C A',c,c-36);ctx.fillStyle='rgba(238,233,223,.48)';ctx.font='600 6px "Arial Narrow", "Segoe UI", sans-serif';ctx.fillText('BROOKLYN · PRIVATE STUDIO',c,c+39);const hand=(angle,front,back,width,color)=>{ctx.beginPath();ctx.moveTo(c-Math.cos(angle)*back,c-Math.sin(angle)*back);ctx.lineTo(c+Math.cos(angle)*front,c+Math.sin(angle)*front);ctx.lineWidth=width;ctx.lineCap='round';ctx.strokeStyle=color;ctx.stroke()};const hour=(now.getHours()%12+now.getMinutes()/60)*Math.PI/6-Math.PI/2,minute=(now.getMinutes()+now.getSeconds()/60)*Math.PI/30-Math.PI/2,second=(now.getSeconds()+now.getMilliseconds()/1000)*Math.PI/30-Math.PI/2;hand(hour,48,10,7,accent);hand(minute,72,12,4,'#eee9df');hand(second,84,18,1.5,'#f25c52');ctx.beginPath();ctx.arc(c,c,6,0,Math.PI*2);ctx.fillStyle=authority;ctx.fill();ctx.beginPath();ctx.arc(c,c,2,0,Math.PI*2);ctx.fillStyle='#050707';ctx.fill();ctx.restore()}
$('#themeToggle').addEventListener('click',()=>{const menu=$('#themeMenu'),open=menu.hidden;menu.hidden=!open;$('#themeToggle').setAttribute('aria-expanded',String(open))});
$('#themeClose').addEventListener('click',()=>{$('#themeMenu').hidden=true;$('#themeToggle').setAttribute('aria-expanded','false')});
$('#colorWheel').addEventListener('pointerdown',e=>{selectWheel(e);const move=x=>selectWheel(x),up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)});
$('#colorBrightness').addEventListener('input',e=>{customBrightness=Number(e.target.value)/100;setCustomColor(hsvToRgb(customHue,customSat,customBrightness),{moveCursor:false})});
$('#themeMenu').addEventListener('click',e=>{const color=e.target.closest('[data-color]')?.dataset.color;if(color){const rgb=hexRgb(color);if(rgb)setCustomColor(rgb)}});
['colorR','colorG','colorB'].forEach(id=>$('#'+id).addEventListener('change',()=>setCustomColor([$('#colorR').value,$('#colorG').value,$('#colorB').value])));
$('#colorHex').addEventListener('change',e=>{const rgb=hexRgb(e.target.value);if(rgb)setCustomColor(rgb)});
$('#applyCustomColor').addEventListener('click',()=>{setCustomColor([$('#colorR').value,$('#colorG').value,$('#colorB').value],{persist:true});$('#themeMenu').hidden=true;$('#themeToggle').setAttribute('aria-expanded','false')});
function tick(){const now=new Date(),time=now.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit'}),date=now.toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric',year:'numeric'}).toUpperCase()+' · BROOKLYN';$('#clock').textContent=time;$('#today').textContent=date;$('#calendarClock').textContent=time;$('#calendarDate').textContent=date;drawAnalog(now)}
drawColorWheel();setCustomColor(hexRgb(localStorage.getItem('lcn-custom-color')||'#d4ae55'));tick();setInterval(tick,1000);load().then(()=>{const requested=location.hash.slice(1);if(['command','revenue','tasks','calendar','ledger','preview','connections'].includes(requested))showView(requested)});setInterval(load,1000);
